ALTER TABLE "fleet_vehicles" ADD COLUMN "secondary_fuel_type" varchar(20) DEFAULT '' NOT NULL;--> statement-breakpoint
ALTER TABLE "fleet_vehicles" ADD COLUMN "secondary_average_consumption" numeric(6,2) DEFAULT '0' NOT NULL;--> statement-breakpoint
ALTER TABLE "fleet_vehicles" ADD CONSTRAINT "fleet_vehicles_secondary_fuel_check" CHECK (case when length("secondary_fuel_type") = 0 then "secondary_average_consumption" = 0 else "secondary_fuel_type" in ('diesel-s10', 'diesel-s500', 'gasolina-comum', 'etanol-hidratado', 'gnv', 'eletrico') and "secondary_fuel_type" <> "fuel_type" end);--> statement-breakpoint
ALTER TABLE "fleet_vehicles" DROP CONSTRAINT "fleet_vehicles_cost_check", ADD CONSTRAINT "fleet_vehicles_cost_check" CHECK ("average_consumption" >= 0 and "secondary_average_consumption" >= 0 and "other_costs_per_kilometer" >= 0 and "acquisition_amount" >= 0 and "monthly_installment_amount" >= 0 and "annual_vehicle_tax_amount" >= 0 and "annual_insurance_amount" >= 0);